```js
import { createState, collectCoin } from '../logic/score.js';

const SPEED = 200;
const INPUT_DEBOUNCE_MS = 50;

export class GameScene extends Phaser.Scene {
  constructor() {
    super('game');
    this.state = createState();
  }

  create() {
    this.player = this.add.rectangle(400, 300, 24, 24, 0xffcc00);
    this.physics.add.existing(this.player);
    this.coins = this.physics.add.group();
    for (let i = 0; i < 8; i++) this.coins.add(this.add.circle(80 + i * 90, 120, 8, 0xffffff));
    this.physics.add.overlap(this.player, this.coins, (_player, coin) => {
      coin.destroy();
      this.state = collectCoin(this.state);
    });

    const move = _.debounce((dx, dy) => this.player.body.setVelocity(dx * SPEED, dy * SPEED), INPUT_DEBOUNCE_MS);
    this.input.keyboard.on('keydown-LEFT', () => move(-1, 0));
    this.input.keyboard.on('keydown-RIGHT', () => move(1, 0));
    this.input.keyboard.on('keydown-UP', () => move(0, -1));
    this.input.keyboard.on('keydown-DOWN', () => move(0, 1));
    this.input.keyboard.on('keyup', () => move(0, 0));
  }
}
```

Remove update() entirely — movement is now event-driven. Removed the use of createCursorKeys.

